/// <summary>
/// METCoverNoteDP class.
/// </summary>
[SrsReportParameterAttribute(classStr(METSalesOrderShipmentBundlingReportContract))]
public class METSalesOrderShipmentBundlingReportDP extends SrsReportDataProviderPreProcessTempDB //PreProcessTempDB
{
    METOrderShipmentBundlingReportHeaderTmp     bundleHeaderTmp;

    METSalesOrderShipmentBundlingReportContract contract;

    METCommonReportContract        commonReportContract;

    METCoverNoteContract        coverNoteContract;
    METCoverNoteDP              coverNoteDP;

    METPickupAdviceReportDP     pickupAdviceReportDP;
    METPickupAdviceReportContract pickupAdviceReportContract;

    METDangerousGoodsManifestDP metDangerousGoodsManifestDP;

    MetShipmentId               shipmentId;
    MetLoadId                   loadId;
    boolean                     isFirstReport;

    Str1260         bundleHeaderReportGuid;
    Str1260         dangerousGoodsHeaderGuid, coverNoteHeaderGuid, pickupAdviceReportHeaderGuid;


}

Method.Source:
/// <summary>
/// ProcessReport
/// </summary>
public void processReport()
{
    METSalesOrderShipmentLoadHeader     shipmentLoadHeader, shipmentLoadHeaderCount;
    METSalesOrderShipmentLoadLines      shipmentLoadLines;

    bundleHeaderReportGuid = guid2Str(newGuid()); //guid2Str(newGuid());
    contract = this.parmDataContract();

    shipmentId  = contract.parmShipmentId();
    loadId      = contract.parmLoadId();
    isFirstReport = contract.parmIsFirstReport();

    select count(RecId) from shipmentLoadHeaderCount
        where shipmentLoadHeaderCount.LoadId == loadId;

    select firstonly shipmentLoadHeader
        where shipmentLoadHeader.ShipmentId == shipmentId   &&
            shipmentLoadHeader.LoadId == loadId;

    bundleHeaderTmp.LoadID = loadId;
    bundleHeaderTmp.ShipmentID = shipmentId;
    bundleHeaderTmp.Route = shipmentLoadHeader.Route;
    bundleHeaderTmp.RouteStopNum = shipmentLoadHeader.RouteStopNum;
    bundleHeaderTmp.TotalNumOfShipment = shipmentLoadHeaderCount.RecId;
    bundleHeaderTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
    bundleHeaderTmp.insert();

    if (isFirstReport)
    {
        commonReportContract = new METCommonReportContract();

        dangerousGoodsHeaderGuid = guid2Str(newGuid()) ; //guid2str(newGuid());
        commonReportContract.parmRecId(shipmentLoadHeader.RecId);

        metDangerousGoodsManifestDP.parmDataContract(commonReportContract);
        metdangerousGoodsManifestDP.setBundlingGuid(bundleHeaderReportGuid, dangerousGoodsHeaderGuid);
        metDangerousGoodsManifestDP.processReport();

    }

    //CoverNote
    coverNoteContract = new METCoverNoteContract();

    coverNoteHeaderGuid = guid2Str(newGuid());

    coverNoteContract.parmShipmentId(shipmentLoadHeader.ShipmentId);

    coverNoteDP.parmDataContract(coverNoteContract);
    coverNoteDP.setBundlingGuid(bundleHeaderReportGuid, coverNoteHeaderGuid);
    coverNoteDP.processReport();


    while select shipmentLoadHeader
        where shipmentLoadHeader.LoadId == loadId
    {
        pickupAdviceReportContract = new METPickupAdviceReportContract();

        pickupAdviceReportHeaderGuid = guid2Str(newGuid());

        pickupAdviceReportContract.parmShipmentID(shipmentLoadHeader.ShipmentId);

        pickupAdviceReportDP.parmDataContract(pickupAdviceReportContract);
        pickupAdviceReportDP.setBundlingGuid(bundleHeaderReportGuid, pickupAdviceReportHeaderGuid);
        pickupAdviceReportDP.processReport();

    }
}

